<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $session->stock_take_no }}</title><style>body{margin:0;background:#eef3f9;font-family:Arial,sans-serif;color:#12213a}.wrap{max-width:1100px;margin:30px auto;padding:0 16px}.card{background:#fff;border-radius:20px;box-shadow:0 16px 45px rgba(15,23,42,.12);overflow:hidden}.head{padding:28px;background:linear-gradient(135deg,#1d4ed8,#0ea5e9);color:#fff}.head h1{margin:0 0 8px}.body{padding:28px}.meta{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.meta div{border:1px solid #dbe6f3;border-radius:12px;padding:14px}.meta span{display:block;color:#64748b;font-size:12px}.meta strong{font-size:18px}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{padding:10px;border-bottom:1px solid #e7edf5;text-align:left}.num{text-align:right}.actions{display:flex;gap:10px;margin-bottom:20px}.btn{display:inline-block;padding:11px 18px;border-radius:10px;background:#2563eb;color:#fff;text-decoration:none}@media(max-width:700px){.meta{grid-template-columns:1fr 1fr}.body{padding:16px}.table{overflow:auto}}</style></head><body><div class="wrap"><div class="card"><div class="head"><h1>Stock Taking {{ ucwords(str_replace('_',' ',$documentType)) }}</h1><div>{{ $session->stock_take_no }} – {{ $session->title }}</div></div><div class="body"><div class="actions">@if($link->download_allowed)<a class="btn" href="{{ route('stock-taking-new.public.shared.download',['token'=>$token]) }}">Download PDF</a>@endif</div><div class="meta"><div><span>Location</span><strong>{{ $locationName }}</strong></div><div><span>Store</span><strong>{{ $storeName }}</strong></div><div><span>Date</span><strong>{{ optional($session->count_date)->format('d M Y') }}</strong></div><div><span>Status</span><strong>{{ ucfirst($session->status) }}</strong></div><div><span>System Qty</span><strong>{{ number_format((float)$session->system_qty_total,4) }}</strong></div><div><span>Counte